INSERT INTO p_amb_brand (act_id, slug, live, display_name, intro, about, audience, accent, logo_url, submit_platform, submit_url, submit_label, avoid_json, rules_json, season_json, show_inspo, pdf_json) VALUES ('act_313396960515158', 'grunk-dolfer', 0, 'Grunk Dolfer', 'Grunk Dolfer makes loud polos for guys who golf to hang out, not to grind. Golf is a drinking sport, so we want videos that look like a real Saturday: the crew, the cart, the bad shots and the 19th hole. Pick an idea below, film it your way, and submit it on TRYBE like always.', 'Loud, soft performance golf polos in prints you won''t see on anyone else, plus hats, hoodies, koozies and the Den Caddy cart cooler. Relaxed dad bod fit, sizes small through 4XL, and 5XL on many prints. The mascot is Chunkman: a chubby guy holding a beer.', 'Weekend golfers, mostly guys 30 to 55, who play with the same buddies, have a beer on the cart and care more about the day than the score. Plenty have a dad bod and are proud of it. In gift season we also talk to the wives, girlfriends and kids buying for them.', '#E05A25', NULL, 'TRYBE', NULL, 'Film this on TRYBE', '[{"title": "Holding a product up to the camera in front of a wall or shelf, and nothing else happens", "why": "Most of what we get looks exactly like this. Take us to the course, the cart, the bar or the group chat instead."}, {"title": "A hat or accessory video that talks about polos", "why": "Talk about the thing you are showing. If it is a hat, sell the hat."}, {"title": "Stiff, posed shots smiling at the camera", "why": "Our posed ads lose. Real rounds, real buddies and real reactions win."}, {"title": "Opening on another brand''s shirt", "why": "Keep the first seconds on Grunk. A plain unbranded polo is fine later in the video."}, {"title": "Shotgunning, chugging, or anyone who looks drunk", "why": "A beer in hand is the brand. Getting hammered on camera breaks ad rules."}, {"title": "Reading the product page out loud", "why": "Say one thing it does and show the rest. Nobody stops scrolling for a spec list."}]', '["Say what the site says: soft, 4-way stretch, moisture-wicking, breathable, wrinkle-resistant, relaxed dad bod fit.", "Never say UPF, sun protection, stain-proof or beer-proof about a polo. Never say HYDR18 prevents or cures hangovers.", "Sizes: every polo comes small through 4XL, and many prints go to 5XL. Check the product page before you say 5XL.", "Only mention an offer that is live on the site. The Black Friday deal (BOGO + 30% off sitewide) goes in Black Friday videos only.", "If there is alcohol on screen, everyone is 21 or older. A beer in hand is fine. No chugging, and nobody drinks and drives, golf carts included.", "Show the print up close at least once and say the print''s name.", "Film vertical, sound on, and show where you are in the first two seconds.", "Only film people who agreed to be in your video, on a course that allows filming."]', '{"title": "Fall golf season", "until": "Nov 25", "line": "Scrambles, charity outings, guys'' trips and cooler rounds. We are pushing the new fall drops (Brown Chunkman, Espresso Martini, Closet Grunk) and the Den Caddy with a free polo. Start your gift videos now so they are ready for November.", "next": "Black Friday (BOGO + 30% off sitewide) and holiday gifting, from Nov 26", "highlight": ["09-15", "11-25"], "show_chart": true, "color": "#B45309", "cap": null, "mode": "custom", "custom": {"1": 20, "2": 20, "3": 25, "4": 26, "5": 34, "6": 36, "7": 38, "8": 32, "9": 30, "10": 30, "11": 33, "12": 32, "13": 34, "14": 50, "15": 38, "16": 28, "17": 27, "18": 27, "19": 28, "20": 33, "21": 34, "22": 36, "23": 44, "24": 55, "25": 42, "26": 36, "27": 34, "28": 25, "29": 24, "30": 23, "31": 24, "32": 24, "33": 23, "34": 18, "35": 17, "36": 15, "37": 14, "38": 15, "39": 18, "40": 30, "41": 32, "42": 28, "43": 22, "44": 22, "45": 28, "46": 32, "47": 45, "48": 100, "49": 55, "50": 65, "51": 64, "52": 55, "53": 40}}', 1, '{"line1": "Grunk Dolfer creators,", "line2": "here''s what to film.", "intro": "Golf is a drinking sport, and our creator hub shows you how to film it: this week''s hot picks, the fall drops, gift season, openers you can say word for word, and real videos that worked. It updates on its own, so check it before you shoot.", "cta": "Your creator hub", "note": "Opens right on your phone. No login, no app.", "steps": ["Open the hub and pick an idea", "Film it your way, starting with the opener", "Submit on TRYBE with the idea''s name"]}');
