INSERT INTO p_amb_section (id, act_id, name, line, icon, icon_svg, color, enabled, pinned, sort) VALUES ('d5f153f2b2c9ca54', 'act_313396960515158', 'Masters to Father''s Day', 'Masters week, watch parties and Father''s Day. Switch on in March.', 'flag', '<path d="M4 22V4a1 1 0 0 1 .4-.8A6 6 0 0 1 8 2c3 0 5 2 7.333 2q2 0 3.067-.8A1 1 0 0 1 20 4v10a1 1 0 0 1-.4.8A6 6 0 0 1 16 16c-3 0-5-2-8-2a6 6 0 0 0-4 1.528"/>', '#166534', 0, 0, 7);
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, lever, openers_json, shots_json, on_screen, do_text, dont_text, trend) VALUES ('fc61b7e0366eb10f', 'act_313396960515158', '47b32baee763abf6', 1, 1, 1, 'live', 'The new drop, ranked by beers deep', 'The fall drop is here, and the only fair way to rank it is how many beers deep you''d be wearing each one.', 'The collector who buys every drop, and anyone who likes a ranking.', 'Fall drops: Brown Chunkman, Espresso Martini, Closet Grunk, Bearly Sober', 'Try-on haul', 'Curiosity', '["Ranking the new Grunk drop by how many beers deep I am.", "New Grunk just landed. One of these is a four beer shirt.", "I tried on the whole fall drop so you don''t have to."]', '[{"label": "Open \u00b7 0 to 3s", "text": "Hold all the new pieces fanned out to camera, a beer in the other hand. Say the opener."}, {"label": "Middle", "text": "Try each one on, fast cuts. Say the print name, give it a beers-deep score (1 to 5) and one reason. Big number on screen for each."}, {"label": "Close", "text": "Crown the winner. Close-up on the print, then you walking out the door in it."}]', 'NEW DROP: RANKED BY BEERS DEEP', 'Say every print name out loud: Brown Chunkman, Espresso Martini, Closet Grunk, Bearly Sober.', 'Rank them all the same. Pick a clear winner and a clear loser, that is the fun.', NULL);
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, ad_id, shown, sort) VALUES ('5289ace2f8722d11', 'act_313396960515158', 'fc61b7e0366eb10f', 'meta', '120242005365750115', 1, 1);
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, lever, openers_json, shots_json, on_screen, do_text, dont_text, trend) VALUES ('4cb66056cae49dd2', 'act_313396960515158', '47b32baee763abf6', 1, 2, 2, 'live', 'Closet Grunk: yes, you can wear it to dinner', 'Closet Grunk looks like a normal shirt from across the room, so you can finally wear Grunk to dinner and win the argument.', 'The guy whose partner always vetoes the loud polo at the restaurant.', 'Closet Grunk button downs', 'Couple skit', 'Humor', '["\"You are not wearing a golf shirt to dinner.\" Watch this.", "She said no golf shirts at dinner. She didn''t say no Grunk.", "The one Grunk shirt my wife lets out of the house."]', '[{"label": "Open \u00b7 0 to 3s", "text": "Partner blocks the door: \"You are not wearing a golf shirt to dinner.\""}, {"label": "Middle", "text": "He comes back in the Closet Grunk button down. She checks it from across the room: \"Fine. That one is nice.\" Wide shot so it looks plain."}, {"label": "Close", "text": "Cut to the restaurant. Slow push in to the tonal camo up close. He winks at camera."}]', 'From across the room: normal. Up close: Grunk.', 'Shoot the reveal wide, then close. The joke is the distance.', 'Let the partner be mean. Keep it teasing.', NULL);
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, lever, openers_json, shots_json, on_screen, do_text, dont_text, trend) VALUES ('0deab03273f532c5', 'act_313396960515158', '47b32baee763abf6', 1, 3, 3, 'live', 'The Den Caddy rolls up to the first tee', 'Everyone else brings a bag; you bring a cold 24-can bar to the first tee, and the polo comes free with it.', 'The guy who hosts the round, and every buddy who wishes he did.', 'Den Caddy + free polo', 'Reaction reveal', 'Status', '["Some guys show up with a golf bag. I showed up with this.", "My buddies when I rolled the Den Caddy up to the first tee.", "It came with a free polo. I''m not even mad."]', '[{"label": "Open \u00b7 0 to 3s", "text": "Film your buddies at the first tee. Roll the Den Caddy into frame. Get their real faces."}, {"label": "Middle", "text": "Open it up: cans inside, cold. Hand them out. Show the free polo you are wearing."}, {"label": "Close", "text": "Group cheers on the tee box, Den Caddy in the middle of the shot."}]', 'The Den Caddy. Your polo is on us.', 'Say it holds 20 to 24 cans and that a polo comes free with it (check the site that the free polo is still on).', 'Show the caddy with nobody around. The reactions sell it.', NULL);
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, ad_id, shown, sort) VALUES ('8fd49b89edf810dc', 'act_313396960515158', '0deab03273f532c5', 'meta', '120246364176890115', 1, 1);
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, lever, openers_json, shots_json, on_screen, do_text, dont_text, trend) VALUES ('cb9a6243cea28d16', 'act_313396960515158', '47b32baee763abf6', 0, 0, 4, 'live', 'Espresso Martini at the turn', 'The Espresso Martini polo is the only shirt that matches the best drink at the turn.', 'The guy who treats the turn like happy hour.', 'Espresso Martini polo', 'Bar POV', 'Identity', '["Ordered an espresso martini at the turn. Matched my shirt.", "If your polo matches your drink, you are winning the round.", "Front nine: bad. Espresso martini at the turn: perfect."]', '[{"label": "Open \u00b7 0 to 3s", "text": "POV at the turn: the bartender slides an espresso martini across the counter."}, {"label": "Middle", "text": "Hold the drink up next to the polo. Close-up of the print, then the drink."}, {"label": "Close", "text": "Cheers to camera. Walk back to the cart for the back nine."}]', 'The drink matches the shirt.', NULL, 'Make it about getting drunk. One drink, a good time.', NULL);
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, lever, openers_json, shots_json, on_screen, do_text, dont_text, trend) VALUES ('ed948ad6801e9850', 'act_313396960515158', '47b32baee763abf6', 0, 0, 5, 'live', 'Fall scramble fit check', 'Fall scramble season is when a loud polo and a hoodie do the talking before you even hit a shot.', 'Guys playing fall scrambles, outings and charity tournaments.', 'Polos + hoodies', 'On-course fit check', 'Belonging', '["Fall scramble fit check.", "Cold morning scramble. Hoodie off by hole 3.", "Rating my team''s scramble fits."]', '[{"label": "Open \u00b7 0 to 3s", "text": "Parking lot or range, cold morning. Hoodie on, show it head to toe."}, {"label": "Middle", "text": "Hoodie comes off, the polo underneath. Quick close-up of each print. Your team does the same."}, {"label": "Close", "text": "Team shot at the scramble sign or the first tee."}]', 'FALL SCRAMBLE FIT CHECK', 'Show both layers: the hoodie and the polo under it.', NULL, 'Any "fit check" or outfit-reveal sound.');
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, lever, openers_json, shots_json, on_screen, do_text, dont_text, trend) VALUES ('28f26f922263f85b', 'act_313396960515158', '47b32baee763abf6', 0, 0, 6, 'live', 'Going as a golfer for Halloween', 'The easiest Halloween costume is already in your closet: a loud polo, a beer and a bad swing.', 'The guy who forgot about the Halloween party until today.', 'Chunkman polos, Grunk Dolfer polos', 'Costume skit', 'Humor', '["Forgot my Halloween costume. Went as a golfer.", "My costume this year: guy who says he''ll only have one beer on the course.", "Best Halloween costume under $70."]', '[{"label": "Open \u00b7 0 to 3s", "text": "Everyone at the party in real costumes. You walk in wearing a Grunk polo, beer in hand."}, {"label": "Middle", "text": "Someone asks what you are. \"Golfer.\" Cut to you doing a terrible practice swing in the kitchen."}, {"label": "Close", "text": "Close-up of the print. \"Best costume here.\" Ends Oct 31."}]', 'Costume: golfer. Effort: none.', NULL, 'Post it after Oct 31.', NULL);
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, lever, openers_json, shots_json, on_screen, do_text, dont_text, trend) VALUES ('0e66d41f647f53b1', 'act_313396960515158', 'c59112866caec29e', 1, 4, 1, 'live', 'How long until he notices', 'A Grunk polo is the gift that gets a real reaction, and the fun part is watching him find the joke in the print.', 'Wives and girlfriends buying for a golfer.', 'Chunkman or Drinko polos', 'Gift prank', 'Curiosity', '["I bought my husband a golf polo. Let''s see how long it takes him to notice.", "He thinks it''s a normal golf shirt.", "Timing how long until he sees the Chunkman."]', '[{"label": "Open \u00b7 0 to 3s", "text": "Whisper the opener to camera while he is in the other room. Show the polo (Chunkman or Drinko prints work best)."}, {"label": "Middle", "text": "Hand it over. Keep the camera on his face. Timer on screen."}, {"label": "Close", "text": "He spots it. Real reaction. Stop the timer, close-up of the print."}]', 'Timer: how long until he notices', 'Keep the camera on his face the whole time. The reaction is the ad.', 'Tell him before you film.', NULL);
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, lever, openers_json, shots_json, on_screen, do_text, dont_text, trend) VALUES ('3048e9d771df6111', 'act_313396960515158', 'c59112866caec29e', 1, 5, 2, 'live', 'The golfer who has everything', 'He already has every golf gadget; he doesn''t have a shirt with a personality.', 'Anyone buying for a dad, husband or buddy who is hard to shop for.', 'Grunk Dolfer polos, gift cards', 'Voiceover list', 'Relief', '["What do you get the golfer who has everything?", "He has 40 golf shirts. They are all navy.", "\"Finally found something he didn''t have.\" A real review."]', '[{"label": "Open \u00b7 0 to 3s", "text": "Voiceover over shots of his gear: rangefinder, 6 drivers, a closet of plain polos."}, {"label": "Middle", "text": "The loud Grunk polo appears in the middle of the plain ones. Close-up of the print."}, {"label": "Close", "text": "Him wearing it at the course. \"He wore it every Saturday since.\""}]', 'He has everything. Except this.', NULL, 'Say anything about him you don''t know is true. Keep it your story.', NULL);
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, lever, openers_json, shots_json, on_screen, do_text, dont_text, trend) VALUES ('9572e79fbd45fbe3', 'act_313396960515158', 'c59112866caec29e', 0, 0, 3, 'live', 'Black Friday haul: BOGO + 30% off', 'Black Friday is the one week to stock up: BOGO plus 30% off sitewide.', 'Collectors and gift buyers who wait for the deal. Black Friday week only.', 'Everything (Black Friday)', 'Unboxing', 'Value', '["Grunk Black Friday haul. BOGO plus 30% off everything.", "I waited all year for this sale.", "How many polos I got for Black Friday."]', '[{"label": "Open \u00b7 0 to 3s", "text": "Box on the table, tape cut, beer next to it. Say the deal."}, {"label": "Middle", "text": "Pull out each piece, say the print name and who it is for (you, your dad, your buddy)."}, {"label": "Close", "text": "Everything laid out. Say the deal once more and that it ends Cyber Monday."}]', 'BOGO + 30% OFF SITEWIDE', 'Say the deal exactly as it is on the site.', 'Post this before Black Friday week or after Cyber Monday.', NULL);
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, lever, openers_json, shots_json, on_screen, do_text, dont_text, trend) VALUES ('e4650dc7d35940e1', 'act_313396960515158', 'c59112866caec29e', 0, 0, 4, 'live', 'Dad and lil dude', 'The best gift for a golf dad is a mini version of himself in the same polo.', 'Moms buying for dad and the kids, and golf dads.', 'Kids polos + matching adult polos', 'Matching reveal', 'Belonging', '["Matching polos with my kid. He hits it straighter than me.", "Mini me, same polo.", "Dad and lil dude, range day."]', '[{"label": "Open \u00b7 0 to 3s", "text": "Dad walks into frame in a polo. The kid walks in behind him in the same print."}, {"label": "Middle", "text": "Range or putting green together. Both swings side by side."}, {"label": "Close", "text": "High five, close-up of both prints."}]', 'Dad and lil dude', 'Kids polos come in White Neon Rose, Island Boy and the Hawaiian prints. Check the site.', 'Show the kid with any alcohol in the shot.', NULL);
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, lever, openers_json, shots_json, on_screen, do_text, dont_text, trend) VALUES ('f30907243e40b7e7', 'act_313396960515158', 'c59112866caec29e', 0, 0, 5, 'live', 'The stocking stuffer drawer', 'Grunk makes stocking stuffers golfers actually use, all under $20.', 'Gift buyers filling stockings and secret santa.', 'Koozies, ball markers, divot tools, towels', 'Top-down flat lay', 'Value', '["Stocking stuffers for the golfer, all under 20 bucks.", "Everything in this stocking is for the cart.", "Secret santa for the golf guy, sorted."]', '[{"label": "Open \u00b7 0 to 3s", "text": "Top-down: an empty stocking on the table."}, {"label": "Middle", "text": "Drop each item in, one per beat: magnetic koozie, ball marker, divot tool, towel. Say what each does."}, {"label": "Close", "text": "Full stocking. Cut to him using the koozie on the cart."}]', 'Golf stocking stuffers under $20', 'Check prices on the site before you say them.', NULL, NULL);
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, lever, openers_json, shots_json, on_screen, do_text, dont_text, trend) VALUES ('ebd9ea5902a2c4d2', 'act_313396960515158', 'c59112866caec29e', 0, 0, 6, 'live', 'Christmas money, spent', 'Gift cards and Christmas cash go straight to the polo he actually wanted.', 'Guys who got a gift card or Christmas cash. Dec 26 to Jan 5.', 'Gift cards, polos', 'Screen record', 'Identity', '["What I bought with my Christmas money.", "Got a Grunk gift card. Here''s the damage.", "My wife gave me a gift card so I would stop dropping hints."]', '[{"label": "Open \u00b7 0 to 3s", "text": "Screen record: the gift card or the Venmo from grandma."}, {"label": "Middle", "text": "Scroll the site, add polos to the cart, talk through why each one."}, {"label": "Close", "text": "Checkout, then cut to the box arriving."}]', 'Christmas money: spent', NULL, 'Show a real card number or balance.', NULL);
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, lever, openers_json, shots_json, on_screen, do_text, dont_text, trend) VALUES ('365c5ff4295cf919', 'act_313396960515158', 'b56c90ce67f3ab33', 0, 0, 1, 'live', 'Rated for 19 holes', 'Golf is a drinking sport, so the polo has to last the round and the 19th hole.', 'The Saturday foursome that ends every round at the bar.', 'Grunk Dolfer polos', 'Real round POV', 'Identity', '["Most polos quit after 18. Ours are rated for 19.", "Hole 1 to the 19th hole in one shirt.", "Golf is a drinking sport. Dress like it."]', '[{"label": "Open \u00b7 0 to 3s", "text": "First tee, beer in the cup holder, the crew in loud polos. Text: RATED FOR 19 HOLES."}, {"label": "Middle", "text": "Quick real moments: a bad shot, a good one, the cart, a cheers on the green. Text beats: 4-way stretch, moisture-wicking, breathable."}, {"label": "Close", "text": "The 19th hole bar, everyone still looking sharp. Cheers to camera."}]', 'MOST POLOS QUIT AFTER 18.', 'Use real footage from a real round. The shakier and realer, the better.', 'Show chugging or anyone who looks drunk.', NULL);
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, ad_id, shown, sort) VALUES ('5b9dc74013e4991a', 'act_313396960515158', '365c5ff4295cf919', 'meta', '120249439447190115', 1, 1);
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, ad_id, shown, sort) VALUES ('82fb4870d1b63e24', 'act_313396960515158', '365c5ff4295cf919', 'meta', '120249439374960115', 1, 2);
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, lever, openers_json, shots_json, on_screen, do_text, dont_text, trend) VALUES ('c740caa3fc8330f5', 'act_313396960515158', 'b56c90ce67f3ab33', 0, 0, 2, 'live', 'Rate this polo at the 19th hole', 'Strangers at the bar can''t stop commenting on the polo, so let them score it.', 'Anyone who wonders whether a loud polo is too much.', 'Grunk Dolfer polos', 'Bar interviews', 'Social proof', '["I asked strangers at the 19th hole to rate my polo.", "Walking up to golfers at the bar: rate this shirt, 1 to 10.", "Nobody gave it under an 8."]', '[{"label": "Open \u00b7 0 to 3s", "text": "At the clubhouse bar, mic in hand: \"Rate my polo, 1 to 10.\""}, {"label": "Middle", "text": "4 to 6 quick answers with their score on screen. Keep the funny ones."}, {"label": "Close", "text": "Someone asks where you got it. Close-up of the print."}]', 'Rate this polo 1 to 10', 'Get permission from everyone on camera. Keep the real scores, even the low ones.', 'Script the answers.', NULL);
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, lever, openers_json, shots_json, on_screen, do_text, dont_text, trend) VALUES ('887275f3a2116ea2', 'act_313396960515158', 'b56c90ce67f3ab33', 0, 0, 3, 'live', 'The cart girl''s favourite foursome', 'The cart girl remembers the group in the loud polos.', 'Guys who know the beer cart is the best part of the round.', 'Polos, Donde Esta La Cart Girl hat', 'POV from the cart', 'Belonging', '["POV: you are the cart girl and this foursome rolls up.", "Donde esta la cart girl? Right here.", "The cart girl said we were her favourite group. We tipped well."]', '[{"label": "Open \u00b7 0 to 3s", "text": "POV from the beer cart pulling up to a foursome in loud polos (or the Donde Esta La Cart Girl hat)."}, {"label": "Middle", "text": "The group orders, jokes, tips. Quick cuts of each polo."}, {"label": "Close", "text": "Cart drives off, the group waves. Text: see you on the back nine."}]', 'POV: the cart girl''s favourite group', 'Keep it friendly and respectful. The joke is the guys, not her.', NULL, NULL);
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, lever, openers_json, shots_json, on_screen, do_text, dont_text, trend) VALUES ('c0a90355ad50c8b9', 'act_313396960515158', 'b56c90ce67f3ab33', 0, 0, 4, 'live', 'Hole 1 vs hole 18', 'A hot day and a few beers deep, and the polo still looks like it did on the first tee.', 'Guys who play in the heat and hate a sweaty, wrinkled shirt by the back nine.', 'Grunk Dolfer polos', 'Heat check timelapse', 'Proof', '["Hole 1 vs hole 18. Same shirt, 95 degrees.", "Four beers and 18 holes later.", "Checking my polo every 6 holes."]', '[{"label": "Open \u00b7 0 to 3s", "text": "Hole 1: show the polo, the temperature on your phone."}, {"label": "Middle", "text": "Checks at hole 6, 12 and 18: collar, back, sleeves. Honest look each time."}, {"label": "Close", "text": "Side by side: hole 1 and hole 18."}]', 'HOLE 1 vs HOLE 18', 'Only say what you see. Moisture-wicking and wrinkle-resistant are the claims.', 'Say it never shows sweat or that it is stain-proof.', NULL);
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, lever, openers_json, shots_json, on_screen, do_text, dont_text, trend) VALUES ('33fd27809e1834f5', 'act_313396960515158', 'b56c90ce67f3ab33', 0, 0, 5, 'live', 'How many beers fit in the Den Caddy', 'The Den Caddy holds 20 to 24 cans, which is enough for the whole foursome.', 'The guy who buys the beer for the group.', 'Den Caddy', 'Count demo', 'Proof', '["How many beers fit in the Den Caddy? Let''s count.", "Loading the Den Caddy for a Saturday foursome.", "This is the only caddy I tip in beer."]', '[{"label": "Open \u00b7 0 to 3s", "text": "Empty Den Caddy, a pile of cans next to it."}, {"label": "Middle", "text": "Load them in, counting out loud, number on screen."}, {"label": "Close", "text": "Full. Roll it onto the cart. Mention the free polo if it is still on the site."}]', 'Count with me', 'Use standard 12 oz cans. The site says 20 to 24 fit.', NULL, NULL);
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, lever, openers_json, shots_json, on_screen, do_text, dont_text, trend) VALUES ('a6e0d5e8b62c4b1e', 'act_313396960515158', 'b56c90ce67f3ab33', 0, 0, 6, 'live', 'The weekend golfer in the wild', 'The weekend golfer is a rare species, and you can spot him by his polo.', 'Anyone who loves a nature-documentary parody.', 'Grunk Dolfer polos', 'Nature doc voiceover', 'Humor', '["Here, in his natural habitat, the weekend golfer.", "Observe the male golfer. His plumage is loud.", "The weekend golfer approaches the beer cart."]', '[{"label": "Open \u00b7 0 to 3s", "text": "Hushed nature-doc voice over a wide shot of your buddy on the tee."}, {"label": "Middle", "text": "Narrate his habits: the practice swing, the breakfast ball, the beer cart. Zoom in on the polo: his plumage."}, {"label": "Close", "text": "He hits a bad shot and celebrates anyway. \"Remarkable.\""}]', 'The weekend golfer, in the wild', 'Commit to the voice. The more serious, the funnier.', NULL, NULL);
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, lever, openers_json, shots_json, on_screen, do_text, dont_text, trend) VALUES ('23f3d03e92d8c35b', 'act_313396960515158', '7e2860c8583a8b72', 0, 0, 1, 'live', 'Field of 8: outfitting the guys'' trip', 'The trip photo looks legendary when the whole crew shows up in loud polos.', 'The guy planning the guys'' trip, bachelor party or scramble team.', 'Grunk Dolfer polos', 'Group walkout', 'Belonging', '["Welcome to the bachelor open. Field of 8.", "I outfitted the whole guys'' trip in Grunk.", "The groom gets the loudest polo. That''s the rule."]', '[{"label": "Open \u00b7 0 to 3s", "text": "Title card: THE FIELD. Then each guy walks out in slow motion, name and print on screen."}, {"label": "Middle", "text": "The groom or trip captain last, in the loudest print."}, {"label": "Close", "text": "Group photo on the first tee."}]', 'THE FIELD', 'Use a sports-intro sound. Say each print name.', NULL, 'Any walkout or starting-lineup sound.');
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, lever, openers_json, shots_json, on_screen, do_text, dont_text, trend) VALUES ('33d44b5bca73b2ae', 'act_313396960515158', '7e2860c8583a8b72', 0, 0, 2, 'live', 'Nobody wants to draw this team', 'Show up to the scramble matching and loud, and the other teams notice before you tee off.', 'Scramble and outing teams.', 'Grunk Dolfer polos', 'Arrival reaction', 'Status', '["Nobody at the scramble wanted to draw our team.", "We showed up like this and the other teams gave up.", "Scramble team: we can''t putt, but look at us."]', '[{"label": "Open \u00b7 0 to 3s", "text": "The team walks from the parking lot to the check-in table in matching or clashing Grunk."}, {"label": "Middle", "text": "Reactions from other players, a team photo, a quick real shot."}, {"label": "Close", "text": "The scoreboard (win or lose) and the team still looking good."}]', 'The team nobody wanted to draw', 'Get real reactions. Ask before filming other teams.', NULL, NULL);
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, lever, openers_json, shots_json, on_screen, do_text, dont_text, trend) VALUES ('9ed4e2cd920b585d', 'act_313396960515158', '7e2860c8583a8b72', 0, 0, 3, 'live', 'Foursome roll call', 'Every guy in the group has a print that matches his personality.', 'Buddy groups.', 'Grunk Dolfer polos', 'Trend', 'Belonging', '["Foursome roll call.", "Every group has these four golfers.", "Which one is your buddy?"]', '[{"label": "Open \u00b7 0 to 3s", "text": "Roll call trend: each guy steps into frame."}, {"label": "Middle", "text": "Label each one: the sandbagger, the one who loses 6 balls, the beer guy, the one who takes it too seriously. Each in a different print."}, {"label": "Close", "text": "All four together. Caption asks: which one are you?"}]', 'Which one are you?', 'Ask the question in the caption. It gets comments.', NULL, 'Any roll-call or "every group has" sound.');
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, lever, openers_json, shots_json, on_screen, do_text, dont_text, trend) VALUES ('8890e68fb8cf385f', 'act_313396960515158', '7e2860c8583a8b72', 0, 0, 4, 'live', 'The group chat picked the polos', 'The crew votes, and the loudest print wins every time.', 'Buddy groups planning a trip or event.', 'Grunk Dolfer polos', 'Screen record', 'Belonging', '["Let the group chat pick our trip polos. Big mistake.", "Group chat vote: which Grunk for the scramble?", "We voted. Democracy failed."]', '[{"label": "Open \u00b7 0 to 3s", "text": "Screen record the group chat: a poll with 3 prints."}, {"label": "Middle", "text": "Replies roll in, the loudest print wins."}, {"label": "Close", "text": "Cut to the whole crew wearing it on the course."}]', 'The group chat decided', NULL, 'Show real names or phone numbers.', NULL);
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, lever, openers_json, shots_json, on_screen, do_text, dont_text, trend) VALUES ('d6a16585a50fcba7', 'act_313396960515158', '7e2860c8583a8b72', 0, 0, 5, 'live', 'Loser buys the polos', 'The best side bet is the loser buying everyone a new Grunk.', 'Competitive buddy groups.', 'Grunk Dolfer polos', 'Match with a payoff', 'Humor', '["Loser buys everyone a new polo.", "Worst score today pays for the Grunk order.", "I lost. Here''s what it cost me."]', '[{"label": "Open \u00b7 0 to 3s", "text": "Set the bet on the first tee."}, {"label": "Middle", "text": "Quick highlights and lowlights. Scores on screen."}, {"label": "Close", "text": "The loser opens the site on his phone, mad. Cut to everyone in new polos next round."}]', 'Loser buys the polos', NULL, NULL, NULL);
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, lever, openers_json, shots_json, on_screen, do_text, dont_text, trend) VALUES ('0153b8cbd7a475d1', 'act_313396960515158', '02758e77267b5a00', 0, 0, 1, 'live', 'Small through 5XL on real bodies', 'Grunk fits real golfers, from small to big guys, without clinging to the gut.', 'Big guys burned by brands that run small and tight.', 'Grunk Dolfer polos', 'Size lineup', 'Relief', '["Same polo, five different guys.", "Grunk on every body type. Here''s the fit.", "Big guys, this one''s for you."]', '[{"label": "Open \u00b7 0 to 3s", "text": "A lineup of guys of different sizes, same print."}, {"label": "Middle", "text": "Each says his height, weight and size on screen, and one word on the fit."}, {"label": "Close", "text": "Whole lineup does a swing at the same time."}]', 'Height / weight / size', 'Use each guy''s real size.', 'Say every print comes in 5XL. Check the product page.', NULL);
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, lever, openers_json, shots_json, on_screen, do_text, dont_text, trend) VALUES ('1e9471a987786671', 'act_313396960515158', '02758e77267b5a00', 0, 0, 2, 'live', 'The full swing test', 'The 4-way stretch lets you swing out of your shoes without the shirt fighting you.', 'Guys whose polos pull across the shoulders on the swing.', 'Grunk Dolfer polos', 'Slow motion', 'Proof', '["Full swing test in a Grunk polo.", "Slow motion. Watch the shoulders.", "My swing is bad. My shirt is not the problem."]', '[{"label": "Open \u00b7 0 to 3s", "text": "Driver, full swing, slow motion from behind."}, {"label": "Middle", "text": "Same swing from the front. Point out the stretch across the back and shoulders."}, {"label": "Close", "text": "The ball goes wherever it goes. You laugh."}]', '4-WAY STRETCH', NULL, 'Say it never comes untucked. Just show the swing.', NULL);
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, lever, openers_json, shots_json, on_screen, do_text, dont_text, trend) VALUES ('81b8fc11c1873dea', 'act_313396960515158', '02758e77267b5a00', 0, 0, 3, 'live', 'I fit the Chunkman description', 'Chunkman is proud of his dad bod, and the polo is cut for it.', 'Guys with a beer belly who are done hiding it.', 'Chunkman polos', 'Mirror talk', 'Identity', '["I fit the Chunkman description. So I bought the shirt.", "Dad bod approved. Literally, it says so.", "This polo was made for guys shaped like me."]', '[{"label": "Open \u00b7 0 to 3s", "text": "Mirror, polo on, pat the belly. Say the opener."}, {"label": "Middle", "text": "Point to the Chunkman logo and then yourself. Show the fit: no cling, room to move."}, {"label": "Close", "text": "Walk out to the car with the clubs."}]', 'Dad bod approved', 'Be proud of it. Self-deprecating, never sad.', NULL, NULL);
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, ad_id, shown, sort) VALUES ('7ad55518f0e9a3db', 'act_313396960515158', '81b8fc11c1873dea', 'meta', '120237891762730115', 1, 1);
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, lever, openers_json, shots_json, on_screen, do_text, dont_text, trend) VALUES ('272b582272089693', 'act_313396960515158', '2fa02b93d65753de', 0, 0, 1, 'live', 'Across the fairway, then up close', 'From across the fairway it is a loud polo; up close there is a whole story in the print.', 'Everyone. This is how our best ads sell.', 'Grunk Dolfer polos', 'Print reveal', 'Curiosity', '["You can''t tell from over there. Come closer.", "From the tee box vs up close.", "Wait for the close-up."]', '[{"label": "Open \u00b7 0 to 3s", "text": "Wide shot from 30 yards: you on the tee."}, {"label": "Middle", "text": "Hard cut to a close-up of the print. Slow pan across the details."}, {"label": "Close", "text": "Say the print name. Back to the wide shot, you hit."}]', 'From the tee box vs up close', 'Pick the loudest print you own. The print is the hero.', NULL, NULL);
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, ad_id, shown, sort) VALUES ('50f3dd23ada32484', 'act_313396960515158', '272b582272089693', 'meta', '120237114684920115', 1, 1);
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, lever, openers_json, shots_json, on_screen, do_text, dont_text, trend) VALUES ('3d50366ac7dec363', 'act_313396960515158', '2fa02b93d65753de', 0, 0, 2, 'live', '"Where did you get that?" tally', 'Wear a Grunk polo for one round and count how many people ask where you got it.', 'Anyone who wants to be the guy the group notices.', 'Grunk Dolfer polos', 'Round counter', 'Social proof', '["Counting how many people ask about my polo in one round.", "I got asked \"where did you get that\" this many times.", "Wore it once. Got stopped four times."]', '[{"label": "Open \u00b7 0 to 3s", "text": "Parking lot: counter on screen at 0."}, {"label": "Middle", "text": "Each time someone asks, the counter goes up. Keep the real moments."}, {"label": "Close", "text": "Final count at the 19th hole. Close-up of the print."}]', '"Where did you get that?" count: 0', 'Only count real asks. The real number is the proof.', NULL, NULL);
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, ad_id, shown, sort) VALUES ('2c7c95d7877b7b00', 'act_313396960515158', '3d50366ac7dec363', 'meta', '120239652839210115', 1, 1);
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, lever, openers_json, shots_json, on_screen, do_text, dont_text, trend) VALUES ('fbab8576378bef11', 'act_313396960515158', '2fa02b93d65753de', 0, 0, 3, 'live', 'Retire dad''s polos', 'Nothing against Dad, but the plain stripes and safe navy have to go.', 'The guy with a closet full of boring country club polos.', 'Grunk Dolfer polos', 'Closet purge', 'Identity', '["Nothing against Dad. But these have to go.", "I retired every boring polo I own.", "Closet cleanout: golf edition."]', '[{"label": "Open \u00b7 0 to 3s", "text": "Closet full of plain navy and striped polos."}, {"label": "Middle", "text": "Pull them out one by one into a bag, a quick roast for each. Then hang the Grunk polos."}, {"label": "Close", "text": "Closet before and after, then you in the loudest one."}]', 'Retired: every boring polo', 'Keep the plain polos unbranded on camera.', NULL, NULL);
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, ad_id, shown, sort) VALUES ('5bb42a96fdde229f', 'act_313396960515158', 'fbab8576378bef11', 'meta', '120249603609520115', 1, 1);
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, lever, openers_json, shots_json, on_screen, do_text, dont_text, trend) VALUES ('8f5f40f353416281', 'act_313396960515158', '2fa02b93d65753de', 0, 0, 4, 'live', 'Show and tell: my favourite print', 'The easiest way to sell a Grunk polo is to hold it up and talk about why you love it.', 'Anyone new to the brand.', 'Grunk Dolfer polos', 'Handheld show and tell', 'Proof', '["There''s a blue version? Yes.", "My favourite Grunk print, and why.", "Let me show you the details on this one."]', '[{"label": "Open \u00b7 0 to 3s", "text": "Move the product at the lens in the first second (or wave the Chunkman plush in front of it). Text on screen right away."}, {"label": "Middle", "text": "Talk through the print, the feel, the fit and the sizes. Close-ups."}, {"label": "Close", "text": "Put it on, or show it at the course."}]', 'Put the print name on screen in the first second', 'Film it somewhere real: the course, the cart, your garage bar. Not a blank wall.', 'Talk about polos while showing a hat.', NULL);
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, ad_id, shown, sort) VALUES ('e94de213bddb528d', 'act_313396960515158', '8f5f40f353416281', 'meta', '120244036055130115', 1, 1);
