INSERT INTO p_amb_proof (id, act_id, angle_id, kind, ad_id, shown, sort) VALUES ('ca9a97f5e96edc7d', 'act_313396960515158', '8f5f40f353416281', 'meta', '120250165745930115', 1, 3);
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, lever, openers_json, shots_json, on_screen, do_text, dont_text, trend) VALUES ('6be325109cac646d', 'act_313396960515158', '2fa02b93d65753de', 0, 0, 5, 'live', 'The lucky shirt', 'You might not play better in it, but plenty of guys swear they do.', 'Superstitious golfers, which is all of them.', 'Grunk Dolfer polos', 'Scorecard vs outfit split', 'Humor', '["First time I wore it, I broke 100. Just saying.", "My scorecard vs my outfit.", "Shot 104. Won the fit."]', '[{"label": "Open \u00b7 0 to 3s", "text": "Split screen: left the scorecard, right the full outfit."}, {"label": "Middle", "text": "Tell the story of your best (or funniest) round in the shirt."}, {"label": "Close", "text": "The shirt goes back in the closet on a special hanger."}]', 'Scorecard vs outfit', 'Tell your real story, good or bad.', 'Say the shirt will make anyone play better.', NULL);
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, lever, openers_json, shots_json, on_screen, do_text, dont_text, trend) VALUES ('bfa08fd293f9cf7d', 'act_313396960515158', '2fa02b93d65753de', 0, 0, 6, 'live', 'Collector''s closet tour', 'One Grunk polo turns into a collection, and every print has a story.', 'Collectors and Drinking Club members, and anyone who has two already.', 'Grunk Dolfer polos, Drinking Club', 'Closet tour', 'Belonging', '["It started with one polo.", "Closet tour: my Grunk collection.", "My wife says I have a problem. Here is the problem."]', '[{"label": "Open \u00b7 0 to 3s", "text": "Open the closet: a wall of Grunk."}, {"label": "Middle", "text": "Pull out your top 5 and say where you wore each one."}, {"label": "Close", "text": "The empty hanger for the next drop."}]', 'It started with one polo', NULL, NULL, NULL);
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, lever, openers_json, shots_json, on_screen, do_text, dont_text, trend) VALUES ('dd2744b1af1530f8', 'act_313396960515158', '2fa02b93d65753de', 0, 0, 7, 'live', 'You''re not wearing that to dinner', 'A Grunk polo is too good to take off after the round, whatever your partner says.', 'Couples, and guys who wear their golf shirt everywhere.', 'Grunk Dolfer polos', 'Couple argument', 'Humor', '["\"You cannot wear that polo to dinner.\"", "Me leaving the course and going straight to dinner.", "She said change. I said no."]', '[{"label": "Open \u00b7 0 to 3s", "text": "Partner at the door: \"You cannot wear that polo to dinner.\""}, {"label": "Middle", "text": "\"Why? What''s wrong with it?\" Close-up of the print. One-line comeback: \"Golf is a drinking sport, and dinner has drinks.\""}, {"label": "Close", "text": "Cut to dinner. He is wearing it. She is laughing."}]', '"You cannot wear that to dinner"', 'Keep it under 15 seconds. Conflict first line.', NULL, NULL);
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, lever, openers_json, shots_json, on_screen, do_text, dont_text, trend) VALUES ('8b6e246f495b79b1', 'act_313396960515158', 'd5f153f2b2c9ca54', 0, 0, 1, 'live', 'More muni than Masters', 'You''re not getting a green jacket, but you can host the best Masters party in the loudest shirt.', 'Party-golf fans watching the Masters with the crew.', 'Smashters hat, Yellow ChunkMan polo, Grunk Masters Hat', 'Watch party', 'Belonging', '["More muni than Masters.", "Masters Sunday, my living room edition.", "The Smashters hat is better than a green jacket. Hot take."]', '[{"label": "Open \u00b7 0 to 3s", "text": "Living room watch party, Masters on the TV (don''t show the broadcast logo), the crew in Smashters hats and green polos."}, {"label": "Middle", "text": "Putting contest on the carpet, drinks, reactions to the TV."}, {"label": "Close", "text": "Someone \"wins\" and gets a Smashters hat instead of a jacket."}]', 'More muni than Masters', NULL, 'Show the Masters logo or broadcast on screen. Say "Masters week", nothing official.', NULL);
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, ad_id, shown, sort) VALUES ('30d43b991c74c3bb', 'act_313396960515158', '8b6e246f495b79b1', 'meta', '120250256805700115', 1, 1);
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, lever, openers_json, shots_json, on_screen, do_text, dont_text, trend) VALUES ('975c76ceb69f3639', 'act_313396960515158', 'd5f153f2b2c9ca54', 0, 0, 2, 'live', 'Father''s Day: the one he''ll actually wear', 'Skip the tie. Dad will actually wear a Grunk polo every Saturday.', 'Kids and wives shopping for Father''s Day.', 'Polos, Grunk Fathers, kids matching polos', 'Gift reveal', 'Relief', '["Father''s Day gift he''ll actually wear.", "Dad opens his Father''s Day gift. Watch his face.", "Last year I got him a tie. This year I got it right."]', '[{"label": "Open \u00b7 0 to 3s", "text": "Dad opens the gift. Camera on his face."}, {"label": "Middle", "text": "He holds it up, reads the print, laughs."}, {"label": "Close", "text": "Cut to him wearing it on the course that weekend."}]', 'Father''s Day, done right', NULL, NULL, NULL);
